#!/bin/sh -e
# CPU integration test for per-profile ungapped p-value filter (manual).
# Usage: MMSEQS_BIN=/path/to/mmseqs sh src/test/TestTinyProfileCpuFilter.sh
# Fixtures: src/test/tiny_mix.sto, tiny_polyW.sto, tiny_target.fasta, all
# generated by src/test/gen_tiny_profile_fixtures.py (see its docstring for the
# seeds and the CPython version). The p=0.05 golden scores below are tied to
# those fixtures and must be updated when they are regenerated.
FAIL=0
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
if [ -n "$MMSEQS_BIN" ]; then MMSEQS="$MMSEQS_BIN"; fi
if [ -z "$MMSEQS" ]; then
  if [ -x "$ROOT/build-cuda/src/mmseqs" ]; then MMSEQS="$ROOT/build-cuda/src/mmseqs"; fi
fi
if [ -z "$MMSEQS" ]; then MMSEQS="mmseqs"; fi
echo "MMSEQS=$MMSEQS"
command -v "$MMSEQS" >/dev/null 2>&1 || { echo "SKIP: mmseqs binary not found"; exit 0; }
T=$(mktemp -d)
trap 'rm -rf "$T"' EXIT INT TERM
TD="$ROOT/src/test"

for Q in mix polyW; do
  if [ "$Q" = "mix" ]; then F=tiny_mix.sto; else F=tiny_polyW.sto; fi
  "$MMSEQS" convertmsa "$TD/$F" "$T/$Q.msa" --identifier-field 0 >/dev/null
  "$MMSEQS" msa2profile "$T/$Q.msa" "$T/$Q.prof" --threads 1 >/dev/null
done
"$MMSEQS" createdb "$TD/tiny_target.fasta" "$T/targetDB" --threads 1 >/dev/null

# Score-level prefilter golden (exact hit set + scores at p=0.05).
"$MMSEQS" ungappedprefilter "$T/mix.prof" "$T/targetDB" "$T/pref05" \
  --prefilter-mode 1 --ungapped-pvalue 0.05 --gpu 0 --threads 1 >/dev/null
"$MMSEQS" createtsv "$T/mix.prof" "$T/targetDB" "$T/pref05" "$T/pref05.tsv" >/dev/null
sort "$T/pref05.tsv" > "$T/pref05.sorted"
printf 'tiny_mix\tt10\t25\t0\ntiny_mix\tspike_exact\t105\t0\ntiny_mix\tspike_mut70\t53\t0\n' > "$T/pref05.golden"
sort "$T/pref05.golden" > "$T/pref05.golden.sorted"
if diff -q "$T/pref05.golden.sorted" "$T/pref05.sorted" >/dev/null; then
  echo "ok: p=0.05 golden scores"
else
  echo "FAIL: p=0.05 golden scores mismatch"; diff "$T/pref05.golden.sorted" "$T/pref05.sorted" | head; FAIL=1
fi
# p=1.0 (gate off) must be a strict, score-preserving superset of p=0.05.
"$MMSEQS" ungappedprefilter "$T/mix.prof" "$T/targetDB" "$T/pref10" \
  --prefilter-mode 1 --ungapped-pvalue 1.0 --gpu 0 --threads 1 >/dev/null
"$MMSEQS" createtsv "$T/mix.prof" "$T/targetDB" "$T/pref10" "$T/pref10.tsv" >/dev/null
NP05=$(wc -l < "$T/pref05.tsv"); NP10=$(wc -l < "$T/pref10.tsv")
MISS=0
while IFS= read -r row; do
  grep -Fqx "$row" "$T/pref10.tsv" || { MISS=1; echo "FAIL: p=1.0 missing/score-changed row: $row"; }
done < "$T/pref05.tsv"
if [ "$MISS" = "0" ] && [ "$NP10" -gt "$NP05" ]; then
  echo "ok: p=1.0 score-preserving strict superset ($NP05 -> $NP10)"
else
  [ "$MISS" = "0" ] || FAIL=1
  [ "$NP10" -gt "$NP05" ] || { echo "FAIL: p=1.0 not a strict superset ($NP05 -> $NP10)"; FAIL=1; }
fi

# mix query: determinism + cache reuse + superset + spike kept
"$MMSEQS" search "$T/mix.prof" "$T/targetDB" "$T/ali1" "$T/tmp1" \
  --prefilter-mode 1 --ungapped-pvalue 0.05 --ungapped-calib "$T/calib.tsv" --threads 1 >/dev/null
"$MMSEQS" search "$T/mix.prof" "$T/targetDB" "$T/ali2" "$T/tmp2" \
  --prefilter-mode 1 --ungapped-pvalue 0.05 --ungapped-calib "$T/calib.tsv" --threads 1 >/dev/null
"$MMSEQS" search "$T/mix.prof" "$T/targetDB" "$T/ali3" "$T/tmp3" \
  --prefilter-mode 1 --ungapped-pvalue 0.05 --ungapped-calib "$T/calib.tsv" \
  --ungapped-recalibrate --threads 1 >/dev/null
"$MMSEQS" createtsv "$T/mix.prof" "$T/targetDB" "$T/ali1" "$T/ali1.m8" >/dev/null
"$MMSEQS" createtsv "$T/mix.prof" "$T/targetDB" "$T/ali2" "$T/ali2.m8" >/dev/null
"$MMSEQS" createtsv "$T/mix.prof" "$T/targetDB" "$T/ali3" "$T/ali3.m8" >/dev/null
if diff -q "$T/ali1.m8" "$T/ali2.m8" >/dev/null && diff -q "$T/ali1.m8" "$T/ali3.m8" >/dev/null; then
  echo "ok: determinism run1==run2==recalibrate"
else echo "FAIL: nondeterministic hits"; FAIL=1; fi
if head -1 "$T/calib.tsv" | grep -q "#v3" && [ "$(grep -vc "^#" "$T/calib.tsv")" = "1" ]; then
  echo "ok: calib.tsv header+rows"
else
  echo "FAIL: calib.tsv header/rows wrong"; FAIL=1
fi
if grep -q "spike_exact" "$T/ali1.m8"; then
  echo "ok: spike_exact kept"
else
  echo "FAIL: spike_exact not kept at p=0.05"; FAIL=1
fi
"$MMSEQS" search "$T/mix.prof" "$T/targetDB" "$T/aliLoose" "$T/tmpL" \
  --prefilter-mode 1 --ungapped-pvalue 1.0 --threads 1 >/dev/null
"$MMSEQS" createtsv "$T/mix.prof" "$T/targetDB" "$T/aliLoose" "$T/aliLoose.m8" >/dev/null
N05=$(wc -l < "$T/ali1.m8"); N10=$(wc -l < "$T/aliLoose.m8")
if [ "$N10" -ge "$N05" ]; then
  echo "ok: superset p1.0 ($N10) >= p0.05 ($N05)"
else
  echo "FAIL: p=1.0 ($N10) not superset of p=0.05 ($N05)"; FAIL=1
fi
# polyW calibrates (row present) — K divergence asserted in TestProfileCalib unit
"$MMSEQS" search "$T/polyW.prof" "$T/targetDB" "$T/aliW" "$T/tmpW" \
  --prefilter-mode 1 --ungapped-pvalue 0.05 --ungapped-calib "$T/calibW.tsv" --threads 1 >/dev/null
if head -1 "$T/calibW.tsv" | grep -q "#v3"; then
  echo "ok: polyW calibrates"
else
  echo "FAIL: polyW calib missing"; FAIL=1
fi
# mode 3 must hard-error
if "$MMSEQS" search "$T/mix.prof" "$T/targetDB" "$T/aliX" "$T/tmpX" --prefilter-mode 3 --threads 1 >/dev/null 2>&1; then
  echo "FAIL: --prefilter-mode 3 did not error"; FAIL=1
else echo "ok: --prefilter-mode 3 hard-errors"; fi

if [ "$FAIL" = "0" ]; then echo "ALL CPU FILTER TESTS PASSED"; else echo "FAILURES"; exit 1; fi
